    "context": "يبين الجدول التالي ميزان المراجعة بالأرصدة لمؤسسة العدالة حتى تاريخ 2024/12/31م:\nالصندوق (مدين) 50000 | رأس المال (دائن) 170000 | أوراق الدفع (دائن) 35000 | شهرة المحل (مدين) 50000 | الآلات والمعدات (مدين) 30000 | مصروفات النقل والتوزيع (مدين) 55000 | مصروفات صيانة الآلات والمعدات (مدين) 20000 | أوراق القبض (مدين) 25000 | القروض الطويلة الأجل (دائن) 80000 | رواتب العاملين (مدين) 15000 | مصروفات المستلزمات المكتبية (مدين) 10000 | المباني (مدين) 70000 | مصروفات الدعاية والإعلان (مدين) 25000 | براءات الاختراع (مدين) 70000 | مؤسسة الأخوة-دائنون (دائن) 15000 | مصروفات التأمين على الأصول (مدين) 10000 | المسحوبات الشخصية (مدين) 45000 | فواتير الماء والكهرباء (مدين) 25000 | إيرادات تقديم الخدمات (دائن) 200000 | الإجمالي = 500000 للطرفين.",
    "text": "بالرجوع إلى ميزان المراجعة لمؤسسة العدالة: أعد كلاً مما يأتي:\nأ) قائمة الدخل.\nب) قائمة حقوق الملكية.\nج) قائمة المركز المالي (الميزانية العمومية).",
    "answer": "أ) قائمة الدخل:\n- الإيرادات: إيرادات تقديم الخدمات = 200000 دينار.\n- المصروفات: نقل وتوزيع (55000) + صيانة آلات ومعدات (20000) + رواتب عاملين (15000) + مستلزمات مكتبية (10000) + دعاية وإعلان (25000) + تأمين على الأصول (10000) + ماء وكهرباء (25000) = إجمالي المصروفات (160000 دينار).\n- صافي الربح = إجمالي الإيرادات (200000) - إجمالي المصروفات (160000) = 40000 دينار.\n\nب) قائمة حقوق الملكية:\n- رأس المال في بداية المدة: 170000 دينار.\n- يطرح: المسحوبات الشخصية: (45000) دينار.\n+ يضاف: صافي الربح: 40000 دينار.\n= رأس المال في نهاية المدة (صافي حقوق الملكية) = 165000 دينار.\n\nج) قائمة المركز المالي (الميزانية العمومية):\n- الأصول:\n  • أصول متداولة: الصندوق (50000) + أوراق القبض (25000) = 75000 دينار.\n  • أصول ثابتة: الآلات والمعدات (30000) + المباني (70000) = 100000 دينار.\n  • أصول غير ملموسة: شهرة المحل (50000) + براءات الاختراع (70000) = 120000 دينار.\n  • إجمالي الأصول = 75000 + 100000 + 120000 = 295000 دينار.\n- الالتزامات وحقوق الملكية:\n  • التزامات متداولة: أوراق الدفع (35000) + مؤسسة الأخوة (دائنون) (15000) = 50000 دينار.\n  • التزامات غير متداولة: قروض طويلة الأجل = 80000 دينار.\n  • إجمالي الالتزامات = 50000 + 80000 = 130000 دينار.\n  • حقوق الملكية (رأس المال نهاية المدة) = 165000 دينار.\n  • إجمالي الالتزامات وحقوق الملكية = 130000 + 165000 = 295000 دينار (تطابق تام مع إجمالي الأصول).",
    "explanation": "توضح المسألة ترابط القوائم المالية الثلاث: صافي الربح من قائمة الدخل يُرحل إلى حقوق الملكية، ورصيد حقوق الملكية الختامي ينتقل إلى الميزانية العمومية لتحقيق التوازن."
