    "isUnitExam": true,
    "type": "essay",
    "typeLabel": "صح أو خطأ مع التبرير المحاسبي",
    "text": "أضع إشارة (✓) أمام العبارة الصحيحة، وإشارة (✗) أمام العبارة غير الصحيحة في كل مما يأتي، مع تبرير إجابتي:\n1- تُقفل الإيرادات في حساب ملخص الدخل في نهاية المدة المالية.\n2- تُعدّ الأرباح المحتجزة جزءاً من حقوق الملكية.\n3- تؤدي المسحوبات الشخصية إلى زيادة رأس المال.\n4- الإيرادات التشغيلية هي إيرادات ناتجة من نشاط المؤسسة الرئيس.\n5- تُغلق جميع الحسابات الدائمة في نهاية المدة المالية.\n6- الأصول المتداولة هي أصول يُمكن تحويلها إلى نقد خلال مدة قصيرة تقل عن سنة واحدة.\n7- الالتزامات الطويلة الأجل هي التزامات تستحق التسديد خلال مدة تقل عن سنة واحدة.\n8- عند تحقق الخسارة، يُقفل حساب ملخص الدخل في حساب رأس المال.",
    "answer": "1- ( ✓ ) التبرير: لأن الإيرادات حسابات مؤقتة تُقفل بجعلها مدينة وملخص الدخل دائناً لتحديد نتيجة النشاط.\n2- ( ✓ ) التبرير: لأن الأرباح المحتجزة هي أرباح متراكمة لم توزع على الملاك وتُعاد استثمارها بالمنشأة وتتبع حقوق الملكية.\n3- ( ✗ ) التبرير: خطأ؛ لأن المسحوبات الشخصية تُخفض رأس المال وحقوق الملكية وليست تزيدها.\n4- ( ✓ ) التبرير: لأنها الإيرادات المتولدة مباشرة من مزاولة المؤسسة لنشاطها التشغيلي الأساسي.\n5- ( ✗ ) التبرير: خطأ؛ الحسابات الدائمة (الأصول، الالتزامات، حقوق الملكية) لا تُقفل بل ترحل أرصدتها إلى الفترات المالية التالية.\n6- ( ✓ ) التبرير: لأن هذا هو التعريف المحاسبي الدقيق للأصول المتداولة (النقد وما يعادله والمخزون والمدينين خلال سنة أو دورة تشغيلية).\n7- ( ✗ ) التبرير: خطأ؛ الالتزامات طويلة الأجل تستحق السداد خلال مدة تزيد على سنة مالية واحدة.\n8- ( ✓ ) التبرير: صحيح؛ تقفل الخسارة بجعل حساب رأس المال مديناً (لتخفيضه) وحساب ملخص الدخل دائناً.",
