    "context": "",
    "options": [],
    "correct": 0,
    "answer": "• الأزمات الاقتصادية:\nاختلال حاد ومفاجئ في النشاط الاقتصادي يؤدي إلى تراجع النمو، وارتفاع معدلات البطالة، واضطراب حركة الأسواق المالية.\n\n• صندوق النقد الدولي:\nمؤسسة مالية دولية أُنشئت عام 1944م أثناء انعقاد مؤتمر بريتون وودز في الولايات المتحدة الأمريكية، وقد بدأ الصندوق نشاطه رسمياً عام 1945م. واليوم يضم الصندوق في عضويته 191 دولة، ويتولى أداء ثلاث مهام أساسية، هي:\n1- تعزيز التعاون النقدي الدولي.\n2- تشجيع التوسع في التجارة والنمو الاقتصادي.\n3- الحَدّ من السياسات التي قد تُلحِق ضرراً بالرخاء العالمي.\n\n• البنك الدولي:\nمؤسسة مالية دولية تَتبَع لمُنظّمة الأُمَم المتحدة، وتقوم على مبدأ التعاون بين البلدان الأعضاء، وقد صدر قرار بإنشائها في مؤتمر بريتون وودز عام 1944م، وحملت اسم البنك الدولي للإنشاء والتعمير (أصبح جزءاً من مجموعة البنك الدولي لاحقاً)، وهدفت إلى إعادة بناء اقتصادات الدول التي دمّرتها الحرب العالمية الثانية، ورفع مستوى التنمية الاقتصادية في الدول النامية، علماً بأنها بدأت ممارسة أعمالها ومهامها في مطلع عام 1946م.",
    "explanation": "المفاهيم والمصطلحات الأساسية للوحدة الرابعة المعتمدة في دليل المعلم.",
    "isUnitExam": true
