    "text": "أقارن بين السياسة المالية التوسعية والسياسة المالية الانكماشية من حيث المفهوم، والوضع الاقتصادي الذي يدفع الحكومة إلى تبني أي منهما، وأثر تطبيق كل سياسة في النشاط الاقتصادي لاحقاً. (ص 109)",
    "context": "جدول المقارنة المعتمد ص 27 (ص 109 من الكتاب):",
    "options": [],
    "correct": 0,
    "answer": "المقارنة الكاملة وفق ص 109 من المنهاج:\n\n1. المفهوم:\n• السياسة المالية التوسعية: سياسة تنتهجها الحكومة حين يعاني الاقتصاد حالة من الركود أو البطالة، ما يضطرها إلى ضخ أموال أكثر في السوق لدفع عجلة الإنتاج وتلبية الزيادة على الطلب، وتشجيع الاستثمار والاستهلاك.\n• السياسة المالية الانكماشية: سياسة تنتهجها الحكومة للحد من الطلب الكلي في قطاع الاقتصاد إذ تعمل الدولة على كبح جماح التضخم الذي يُعد سبباً للإنفاق الزائد في السوق وهو ما يؤدي إلى ارتفاع كبير في الأسعار ومن ثم استقرار الوضع الاقتصادي.\n\n2. الوضع الاقتصادي الدافع للتبني:\n• التوسعية: حالة الركود الاقتصادي والبطالة.\n• الانكماشية: السيطرة على التضخم وإبطاء النمو الاقتصادي المفرط.\n\n3. أثر التطبيق لاحقاً في النشاط الاقتصادي:\n• التوسعية: زيادة السيولة النقدية لدى الأفراد والشركات، زيادة عدد العمال ومنح مزيد من الأجور ورفعها في بعض الحالات. زيادة الطلب على السلع والخدمات ويتمكن المستثمرون من زيادة الإنتاج وتقليل تكاليفه فتزيد الإيرادات وتتضاعف الأرباح، ما يسمح لهم بإعادة استثمار المال في مشروعات إضافية تفضي إلى انتعاش الاقتصاد وإنهاء حالة الركود السائدة.\n• الانكماشية: إن اتباع هذه السياسة من قِبل الدولة ستعمد إلى حجز كم كبير من النقد وإيداعه في خزينة الدولة فيتبقى قليل من المال لدى الأفراد والشركات لاستخدامه في الاستثمار والإنفاق والاستهلاك سعياً من الدولة لإعادة التوازن الاقتصادي المنشود، وهو ما يحول دون فتح باب التوظيف على مصراعيه ويمنع رفع الأجور ويحد من عملية التشغيل وزيادة الإنتاج فيتقلص الاقتصاد وينكمش ومن ثم ينخفض حجم الطلب الكلي وتضيق الفجوة التضخمية.",
